
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_b1lyp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_b1lyp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.303378169764807e+00, -3.241911226011848e+00, -3.155834425395672e+00, -3.036706752652417e+00, -2.874606593333290e+00, -2.659322918075655e+00, -2.383131186911009e+00, -2.045656367853997e+00, -1.659794213545985e+00, -1.252051706309057e+00, -8.449856330417641e-01, -5.645531713793629e-01, -4.858732735276788e-01, -4.058977975582788e-01, -2.961271625835599e-01, -1.865573156770140e-01, -1.104026995424545e-01, -7.269948131967818e-02, -4.583277306088541e-02, -3.129186050583412e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


